58	func marshalPageToken(pageToken *v1pb.PageToken) (string, error) {
59		b, err := proto.Marshal(pageToken)
60		if err != nil {
61			return "", errors.Wrapf(err, "failed to marshal page token")
62		}
63		return base64.StdEncoding.EncodeToString(b), nil
64	}
